import * as React from "react"

import { cn } from "@/lib/utils"

type FootnotesProps = React.ComponentProps<"section"> & { label?: React.ReactNode }

/** A reference goes to its numbered note; the note can take you back to the exact reading place. */
function Footnotes({ label = "Notes", className, children, "aria-labelledby": labelledBy, ...props }: FootnotesProps) {
  const id = React.useId()
  return <section {...props} data-slot="footnotes" className={cn("db-footnotes", className)} aria-labelledby={labelledBy ?? id}>
    <h3 data-slot="footnotes-label" id={id} className="db-footnotes-label">{label}</h3>
    <ol data-slot="footnotes-list">{children}</ol>
  </section>
}

type FootnoteReferenceProps = Omit<React.ComponentProps<"a">, "href" | "children"> & { noteId: string; number: string | number; label?: string }
function FootnoteReference({ noteId, number, label = `Read note ${number}`, className, ...props }: FootnoteReferenceProps) {
  return <sup data-slot="footnote-reference"><a {...props} className={cn("db-footnote-ref", className)} href={`#${encodeURIComponent(noteId)}`} aria-label={props["aria-label"] ?? label}>{number}</a></sup>
}

type FootnoteProps = React.ComponentProps<"li"> & { id: string; number: string | number; referenceId?: string; returnLabel?: string }
function Footnote({ number, referenceId, returnLabel = `Return to reference ${number}`, className, children, ...props }: FootnoteProps) {
  return <li tabIndex={-1} {...props} data-slot="footnote" className={cn("db-footnote", className)}>
    <span data-slot="footnote-number" className="db-footnote-number" aria-hidden="true">{number}</span>
    <div data-slot="footnote-body">{children}{referenceId ? <a data-slot="footnote-return" className="db-footnote-return" href={`#${encodeURIComponent(referenceId)}`} aria-label={returnLabel}>Return</a> : null}</div>
  </li>
}

export { Footnotes, Footnote, FootnoteReference, type FootnotesProps, type FootnoteProps, type FootnoteReferenceProps }

@layer components {
  /* SPECTRA's scale collision: a citation becomes a full-sized coordinate when called. */
  .db-footnotes { min-inline-size: 0; overflow-wrap: anywhere; container-type: inline-size; }
  .db-footnotes-label { font-size: var(--db-pp); font-weight: 400; color: var(--db-pencil); padding-block-end: var(--db-space-3); border-block-end: var(--db-hairline) solid var(--db-rule-strong); margin-block-end: var(--db-space-5); }
  .db-footnotes > ol { list-style: none; padding: 0; display: grid; gap: var(--db-space-6); }
  .db-footnote { display: grid; grid-template-columns: 3.5rem minmax(0, 1fr); gap: var(--db-space-4); position: relative; scroll-margin-block: var(--db-space-7); font-size: var(--db-p); line-height: 1.55; transition: grid-template-columns var(--db-andante) var(--db-spiccato); }
  .db-footnote-number { font-size: 2.4rem; line-height: 0.95; letter-spacing: -0.06em; font-weight: 300; color: var(--db-pencil); transform-origin: top left; transition: font-size var(--db-andante) var(--db-spiccato), color var(--db-allegro), font-weight var(--db-andante); }
  .db-footnote [data-slot="footnote-body"] { border-inline-start: var(--db-hairline) solid var(--db-rule); padding-inline-start: var(--db-space-4); transition: border-color var(--db-moderato); }
  .db-footnote::before { content: ""; position: absolute; inset-inline-start: 0; inset-block-start: -0.65rem; inline-size: 100%; border-block-start: var(--db-hairline) solid var(--db-rule); transform: scaleX(0); transform-origin: left; transition: transform var(--db-andante) var(--db-exhale); }
  .db-footnote:is(:target, [data-force~="target"]) { grid-template-columns: 5rem minmax(0, 1fr); }
  .db-footnote:is(:target, [data-force~="target"])::before { transform: scaleX(1); }
  .db-footnote:is(:target, [data-force~="target"]) .db-footnote-number { font-size: 4.6rem; font-weight: 500; color: var(--db-accent); }
  .db-footnote:is(:target, [data-force~="target"]) [data-slot="footnote-body"] { border-color: var(--db-rule-strong); animation: db-footnote-answer var(--db-andante) var(--db-exhale); }
  .db-footnote-ref { display: inline-flex; min-inline-size: 28px; min-block-size: 28px; align-items: center; justify-content: center; text-decoration: none; color: var(--db-pencil); font-family: var(--db-voice); font-weight: 500; font-size: 0.5em; scroll-margin-block: var(--db-space-7); }
  .db-footnote-ref:is(:hover, :focus-visible, :target, [data-force~="focus"]) { color: var(--db-accent); }
  .db-footnote-return { display: block; inline-size: fit-content; color: var(--db-pencil); font-family: var(--db-voice); font-size: var(--db-pp); margin-block-start: var(--db-space-3); min-block-size: 32px; text-underline-offset: 0.35em; padding-block: var(--db-space-2); }
  @keyframes db-footnote-answer { 0% { transform: translateY(0.45em) skewY(-2deg); } 60% { transform: translateY(-0.06em) skewY(0.4deg); } 100% { transform: none; } }
  :is([dir="rtl"], [dir="rtl"] *) .db-footnote::before { transform-origin: right; }
  @container (max-width: 320px) { .db-footnote { grid-template-columns: 2.5rem minmax(0, 1fr); gap: var(--db-space-3); } .db-footnote:is(:target, [data-force~="target"]) { grid-template-columns: 3.5rem minmax(0, 1fr); } .db-footnote:is(:target, [data-force~="target"]) .db-footnote-number { font-size: 3.5rem; } }
  @media (prefers-reduced-motion: reduce) { .db-footnote, .db-footnote::before, .db-footnote-number, .db-footnote [data-slot="footnote-body"] { transition: none; animation: none; } }
  @media (forced-colors: active) { .db-footnote:is(:target, [data-force~="target"]) .db-footnote-number { color: Highlight; } }
}
